import{_ as n,o as t,c as o,ah as a}from"./chunks/framework.ChH6X6u6.js";const d=JSON.parse('{"title":"Online payments","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"en/guide/parent/paiements-en-ligne.md","filePath":"src/en/guide/parent/paiements-en-ligne.md"}'),i={name:"en/guide/parent/paiements-en-ligne.md"};function s(r,e,l,h,g,p){return t(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="online-payments" tabindex="-1">Online payments <a class="header-anchor" href="#online-payments" aria-label="Permalink to &quot;Online payments&quot;">​</a></h1><p>This page explains how to track your child&#39;s school fees and settle a payment directly online, without visiting the school.</p><h2 id="tracking-school-fees" tabindex="-1">Tracking school fees <a class="header-anchor" href="#tracking-school-fees" aria-label="Permalink to &quot;Tracking school fees&quot;">​</a></h2><p>On your child&#39;s record, the <strong>Payments</strong> section shows four figures:</p><ul><li><strong>Total due</strong> — the total fee amount for the year.</li><li><strong>Discount</strong> — the amount of any discounts granted.</li><li><strong>Total paid</strong> — what has already been paid, online or at the school.</li><li><strong>Balance</strong> — what&#39;s still owed.</li></ul><p>If an installment plan has been set up, a <strong>Payment plan</strong> table lists each installment with its label, amount, due date and status (<strong>Paid</strong>, <strong>Overdue</strong> or <strong>Upcoming</strong>).</p><p>The full payment history is shown in a second table, with the date, amount, method (mobile money, card, bank deposit…), the fee item involved and the payment&#39;s status (<strong>Paid</strong>, <strong>Pending</strong> or <strong>Failed</strong>). This history includes both your online payments and those collected in person at the school.</p><h2 id="paying-online-by-mobile-money" tabindex="-1">Paying online by mobile money <a class="header-anchor" href="#paying-online-by-mobile-money" aria-label="Permalink to &quot;Paying online by mobile money&quot;">​</a></h2><p>As long as a balance remains, a <strong>Pay online</strong> button appears above the payment figures. To make a payment:</p><ol><li>Click <strong>Pay online</strong>.</li><li>In the <strong>Pay by mobile money</strong> window, choose the <strong>Network</strong> to use (Mixx by Yass, Flooz or T-Money, depending on what your school offers).</li><li>Enter the <strong>Phone number</strong> that will receive the payment request.</li><li>Enter the <strong>Amount</strong> to pay — it cannot exceed the remaining balance.</li><li>Click <strong>Send payment request</strong>.</li><li>Confirm the request you receive on your phone through your mobile money operator.</li></ol><p>The payment immediately appears in the history with status <strong>Pending</strong>, then switches to <strong>Paid</strong> once the transaction is confirmed. If it fails, it appears as <strong>Failed</strong> and you can try again.</p><h2 id="downloading-a-receipt" tabindex="-1">Downloading a receipt <a class="header-anchor" href="#downloading-a-receipt" aria-label="Permalink to &quot;Downloading a receipt&quot;">​</a></h2><p>Once a payment is confirmed, a <strong>Download receipt</strong> link appears next to it in the history — click it to get the receipt as a PDF.</p>',13)])])}const m=n(i,[["render",s]]);export{d as __pageData,m as default};
